+        "<｜DSML｜ invoke name=\"lookup\">",
+        "<｜DSML｜ parameter name=\"query\" string=\"true\">weather</｜DSML｜ parameter>",
+        "</｜DSML｜ invoke>",
+    );
+    let mut parser = DeepSeekV41ToolParser::create(&tools(), Arc::new(tokenizer())).unwrap();
+    let mut output = ToolParserOutput::default();
